def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each token is an integer or an operator '+', '-', '*', '/'.
    Division truncates toward zero as per problem statement.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division trunc towards zero
                # Python's int division with // floors toward -inf, so use int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

def solve(line: str):
    """Parse a single CSV line into a list of fields.
    Supports fields optionally quoted with double quotes. Inside quoted fields,
    commas are treated as literal characters and a pair of double quotes `""`
    represents a literal quote.
    """
    fields = []
    field_chars = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped double quote
                if i + 1 < n and line[i + 1] == '"':
                    field_chars.append('"')
                    i += 1  # Skip the escaped quote
                else:
                    in_quotes = False
                # Do not add the surrounding quote to the field
            else:
                field_chars.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field_chars))
                field_chars = []
            elif ch == '"':
                in_quotes = True
            else:
                field_chars.append(ch)
        i += 1
    # Append the final field (handles empty line as [''])
    fields.append(''.join(field_chars))
    return fields

