def solve(grid):
    """Count islands in a 2‑D grid.
    An island consists of cells whose value represents land (1, '1', or True).
    Cells are connected orthogonally (up, down, left, right).
    """
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def is_land(v):
        return v == 1 or v == '1' or v is True
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    count = 0
    for r in range(rows):
        for c in range(cols):
            if is_land(grid[r][c]) and not visited[r][c]:
                count += 1
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if is_land(grid[nr][nc]) and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
    return count

