def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Rules:
    - '.' means current directory (ignore)
    - '..' means go up one directory (pop if possible)
    - multiple slashes are treated as single '/'
    - result must start with '/' and have no trailing slash (unless root)
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

