def solve(s: str) -> int:
    """Return the length of the longest substring without repeating characters.
    Uses sliding window with a dictionary of last seen positions.
    """
    last_index = {}
    max_len = 0
    start = 0  # start index of current window
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            # character repeated inside current window; move start
            start = last_index[ch] + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

