    """Return the minimum number of coins needed to make ``amount`` using unlimited
    coins of each positive denomination in ``coins``. Return -1 if impossible.
    Handles edge cases such as negative amounts or empty coin lists."""
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Keep only positive coin values and deduplicate
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    # If the smallest coin is larger than amount, impossible
