    # DP array: dp[i] = min coins to make i, INF if unreachable
    INF = amount + 1  # larger than any feasible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
