def solve(a: str, b: str) -> int:
    """Compute the Levenshtein edit distance between strings *a* and *b*.
    Uses classic DP with O(len(a)*len(b)) time and O(min(len(a),len(b))) space.
    """
    m, n = len(a), len(b)
    if m == 0:
        return n
    if n == 0:
        return m
    # Ensure b is the shorter string to use less space.
    if n > m:
        a, b = b, a
        m, n = n, m
    # dp[j] will be the distance between a[:i] and b[:j]
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j - 1], dp[j])  # substitution, insertion, deletion
            prev = cur
    return dp[n]

